document.addEventListener('DOMContentLoaded', () => {
  const root = document.getElementById('judder-test-root');
  if (!root) return;

  // Elements
  const bar30 = document.getElementById('bar-30fps');
  const bar40 = document.getElementById('bar-40fps');
  const bar60 = document.getElementById('bar-60fps');
  const barNative = document.getElementById('bar-native');
  const track30 = document.getElementById('track-30fps');
  const btnToggle = document.getElementById('btn-toggle-motion');
  const speedSelect = document.getElementById('select-motion-speed');
  const labelNativeHz = document.getElementById('label-native-hz');

  const metricFps = document.getElementById('metric-fps');
  const metricDelta = document.getElementById('metric-delta');
  const metricJitter = document.getElementById('metric-jitter');
  const metricClass = document.getElementById('metric-class');
  const metricStatus = document.getElementById('metric-status');
  const metricStability = document.getElementById('metric-stability');

  const calcGameFps = document.getElementById('calc-game-fps');
  const calcDisplayHz = document.getElementById('calc-display-hz');
  const calcVrrCheck = document.getElementById('calc-vrr-check');
  const resRatio = document.getElementById('res-ratio');
  const resHold = document.getElementById('res-hold');
  const resSymmetry = document.getElementById('res-symmetry');
  const resPattern = document.getElementById('res-pattern');
  const resVrr = document.getElementById('res-vrr');
  const resRecommendation = document.getElementById('res-recommendation');

  let isMoving = true;
  let speed = 600; // px/sec
  let posNative = 0;
  let pos60 = 0;
  let pos40 = 0;
  let pos30 = 0;

  let lastTime = performance.now();
  let last60Time = lastTime;
  let last40Time = lastTime;
  let last30Time = lastTime;

  // Delta tracking for refresh rate detection
  const deltas = [];
  let lastTelemetryUpdate = performance.now();

  function updateCadenceCalculator() {
    const targetFps = parseInt(calcGameFps.value, 10) || 40;
    const displayHz = parseInt(calcDisplayHz.value, 10) || 120;
    const isVrr = calcVrrCheck.checked;

    const ratio = Math.round((displayHz / targetFps) * 100) / 100;
    const frameHold = Math.round((1000 / targetFps) * 10) / 10;
    const isInteger = Math.abs(ratio - Math.round(ratio)) < 0.01;

    resRatio.textContent = ratio.toFixed(2) + 'x';
    resHold.textContent = frameHold.toFixed(1) + ' ms';

    if (isInteger) {
      resSymmetry.textContent = 'None (Perfect Cadence)';
      resSymmetry.className = 'text-lg font-black text-emerald-700 mt-1';
      resPattern.textContent = Math.round(ratio) + ' display refreshes per game frame (' + Array(Math.round(ratio)).fill('1').join(':') + ' cadence)';
      if (targetFps === 40 && displayHz === 120) {
        resRecommendation.textContent = 'Optimal 40 FPS balanced mode: 120Hz / 40 = exactly 3 refreshes per frame (25.0 ms hold). Retinal judder is eliminated without paying the 60 FPS GPU rendering penalty.';
      } else if (targetFps === 30 && displayHz === 60) {
        resRecommendation.textContent = 'Even 2:2 cadence (33.3 ms hold). While mathematically even, sample-and-hold OLED displays produce perceived stutter during panning due to long static frame hold times.';
      } else {
        resRecommendation.textContent = 'Even integer cadence (' + Math.round(ratio) + ':1 ratio). Frame delivery is perfectly uniform across display scan cycles.';
      }
    } else if (Math.abs(ratio - 2.5) < 0.05) {
      resSymmetry.textContent = 'Mild (3:2 Pulldown)';
      resSymmetry.className = 'text-lg font-black text-amber-700 mt-1';
      resPattern.textContent = 'Alternating 3 and 2 refreshes per frame (3:2 pulldown = 50.0 ms / 33.3 ms alternating hold)';
      resRecommendation.textContent = 'Classic 3:2 pulldown judder. To achieve judder-free 24 FPS cinema playback, switch display output to 120Hz (5:5 pulldown) or 24Hz.';
    } else if (Math.abs(ratio - 1.5) < 0.05) {
      resSymmetry.textContent = 'Severe (Uneven Repeat)';
      resSymmetry.className = 'text-lg font-black text-rose-700 mt-1';
      resPattern.textContent = 'Alternating 1 and 2 refreshes per frame (16.7 ms / 33.3 ms asymmetric repeat)';
      resRecommendation.textContent = 'Severe rhythmic judder! 40 FPS cannot divide into a 60Hz container cleanly. Enable 120Hz mode on your television or switch the console to standard 30 FPS or 60 FPS.';
    } else {
      resSymmetry.textContent = 'Severe (Uneven Repeat)';
      resSymmetry.className = 'text-lg font-black text-rose-700 mt-1';
      resPattern.textContent = 'Fractional cadence (' + ratio + ' refreshes per frame). Frames repeat with irregular timing across display refresh intervals.';
      resRecommendation.textContent = 'Asymmetric frame cadence detected. Micro-stutters and visual tearing will occur unless Variable Refresh Rate (VRR) is active.';
    }

    if (isVrr) {
      if (targetFps >= 48 && targetFps <= displayHz) {
        resVrr.textContent = 'Native VRR Active: Dynamic 1:1 sync across ' + targetFps + 'Hz to ' + displayHz + 'Hz window.';
      } else if (targetFps < 48) {
        const multiplier = Math.ceil(48 / targetFps);
        resVrr.textContent = 'Below 48Hz VRR Floor - LFC Active (' + multiplier + 'x frame multiplication to ~' + (targetFps * multiplier) + ' Hz). Potential near-black OLED gamma flicker.';
      } else {
        resVrr.textContent = 'Exceeds maximum refresh (' + displayHz + ' Hz). VRR disengages at upper boundary.';
      }
    } else {
      resVrr.textContent = 'Fixed Refresh Rate (VRR Disabled): Delivery is constrained to fixed hardware scan cycles.';
    }
  }

  calcGameFps.addEventListener('change', updateCadenceCalculator);
  calcDisplayHz.addEventListener('change', updateCadenceCalculator);
  calcVrrCheck.addEventListener('change', updateCadenceCalculator);
  speedSelect.addEventListener('change', (e) => {
    speed = parseInt(e.target.value, 10) || 600;
  });

  btnToggle.addEventListener('click', () => {
    isMoving = !isMoving;
    btnToggle.textContent = isMoving ? 'Pause Motion' : 'Resume Motion';
    btnToggle.className = isMoving
      ? 'px-4 py-2 rounded-lg bg-indigo-600 hover:bg-indigo-500 font-bold text-xs uppercase tracking-wider transition-colors'
      : 'px-4 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 font-bold text-xs uppercase tracking-wider transition-colors';
  });

  function animLoop(now) {
    const dt = (now - lastTime) / 1000;
    const deltaMs = now - lastTime;
    lastTime = now;

    if (deltaMs > 1.5 && deltaMs < 100) {
      deltas.push(deltaMs);
      if (deltas.length > 120) deltas.shift();
    }

    const trackWidth = track30 ? track30.clientWidth - 32 : 600;

    if (isMoving && trackWidth > 0) {
      // Native refresh position
      posNative = (posNative + speed * dt) % trackWidth;
      barNative.style.left = posNative + 'px';

      // 60 FPS simulated (step every 16.67ms)
      if (now - last60Time >= 16.66) {
        pos60 = (pos60 + speed * ((now - last60Time) / 1000)) % trackWidth;
        bar60.style.left = pos60 + 'px';
        last60Time = now;
      }

      // 40 FPS simulated (step every 25.0ms)
      if (now - last40Time >= 24.99) {
        pos40 = (pos40 + speed * ((now - last40Time) / 1000)) % trackWidth;
        bar40.style.left = pos40 + 'px';
        last40Time = now;
      }

      // 30 FPS simulated (step every 33.33ms)
      if (now - last30Time >= 33.32) {
        pos30 = (pos30 + speed * ((now - last30Time) / 1000)) % trackWidth;
        bar30.style.left = pos30 + 'px';
        last30Time = now;
      }
    }

    // Telemetry updates every 500ms
    if (now - lastTelemetryUpdate > 500 && deltas.length > 20) {
      lastTelemetryUpdate = now;
      const sum = deltas.reduce((a, b) => a + b, 0);
      const meanDelta = sum / deltas.length;
      const rawFps = Math.round(1000 / meanDelta);

      const variance = deltas.reduce((a, b) => a + Math.pow(b - meanDelta, 2), 0) / deltas.length;
      const jitter = Math.round(Math.sqrt(variance) * 100) / 100;
      const stability = Math.max(0, Math.min(100, Math.round(100 - jitter * 15)));

      metricFps.textContent = rawFps;
      metricDelta.textContent = (Math.round(meanDelta * 10) / 10).toFixed(1);
      metricJitter.textContent = jitter.toFixed(2);
      metricStability.textContent = 'Stability: ' + stability + '%';

      let hzClass = 'Other';
      if (rawFps >= 57 && rawFps <= 63) hzClass = '60Hz Standard';
      else if (rawFps >= 72 && rawFps <= 78) hzClass = '75Hz Gaming';
      else if (rawFps >= 115 && rawFps <= 125) hzClass = '120Hz High-Refresh';
      else if (rawFps >= 138 && rawFps <= 148) hzClass = '144Hz Esports';
      else if (rawFps >= 230 && rawFps <= 248) hzClass = '240Hz High-Speed';

      metricClass.textContent = hzClass + ' detected';
      labelNativeHz.textContent = rawFps + ' Hz';
      metricStatus.textContent = hzClass;
    }

    requestAnimationFrame(animLoop);
  }

  updateCadenceCalculator();
  requestAnimationFrame(animLoop);
});
